package com.pvmhud.overlay;

import com.pvmhud.PvMHUDConfig;
import com.pvmhud.tracking.CorruptionTracker;
import com.pvmhud.tracking.DeathChargeTracker;
import com.pvmhud.tracking.HeartTracker;
import com.pvmhud.tracking.MarkOfDarknessTracker;
import com.pvmhud.tracking.ThrallTracker;
import com.pvmhud.tracking.TimeConstants;
import com.pvmhud.tracking.VengeanceTracker;
import com.pvmhud.tracking.WardOfArceuusTracker;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class VengeanceDisplayTest {
    private final PvMHUDConfig config = new PvMHUDConfig() {};
    // Drive varbit events directly without polling a live game client.
    private final VengeanceTracker vengeance = new VengeanceTracker() {
        @Override
        protected void sync() {}
    };
    private final HudVisualStateManager manager = new HudVisualStateManager(
            config,
            new ThrallTracker() {
                @Override
                protected void sync() {}
            },
            vengeance,
            new DeathChargeTracker() {
                @Override
                protected void sync() {}
            },
            new MarkOfDarknessTracker(),
            new CorruptionTracker() {
                @Override
                protected void sync() {}
            },
            new WardOfArceuusTracker() {
                @Override
                protected void sync() {}
            },
            new HeartTracker() {
                @Override
                protected void sync() {}
            }
    );
    private final TrackerDisplay display = manager.displays().stream()
            .filter(candidate -> candidate.tracker == vengeance)
            .findFirst().get();
    private final VisualState state = display.state;
    private long now = TimeConstants.secondsToNanos(100);

    @Test
    public void consumedIconPersistsThroughCooldownAndReadyTimeoutThenRecastRestoresRed() {
        manager.update(now);
        assertFalse(manager.shouldRender(state, now, true));

        change(VarbitID.VENGEANCE_TIMELIMIT, 30);
        change(VarbitID.VENGEANCE_REBOUND, 1);
        assertIcon(SpriteID.LunarMagicOn.VENGEANCE);
        assertTrue(manager.shouldRender(state, now, false));

        change(VarbitID.VENGEANCE_REBOUND, 0);
        assertTrue(state.cooldown);
        assertIcon(SpriteID.LunarMagicOn.VENGEANCE_OTHER);
        assertTrue(manager.shouldRender(state, now, false));

        change(VarbitID.VENGEANCE_TIMELIMIT, 0);
        assertTrue(state.ready);
        assertIcon(SpriteID.LunarMagicOn.VENGEANCE_OTHER);
        assertTrue(manager.shouldRender(state, now, true));
        assertFalse(manager.shouldRender(state, now, false));

        now += TimeConstants.secondsToNanos(config.inactiveSpellTimeoutSeconds() + 1);
        manager.update(now);
        assertFalse(manager.shouldRender(state, now, true));

        change(VarbitID.VENGEANCE_TIMELIMIT, 30);
        change(VarbitID.VENGEANCE_REBOUND, 1);
        assertIcon(SpriteID.LunarMagicOn.VENGEANCE);
        assertTrue(manager.shouldRender(state, now, true));
    }

    @Test
    public void endingCooldownDoesNotTurnStoredVengeanceWhite() {
        change(VarbitID.VENGEANCE_TIMELIMIT, 30);
        change(VarbitID.VENGEANCE_REBOUND, 1);
        change(VarbitID.VENGEANCE_TIMELIMIT, 0);
        assertTrue(state.active);
        assertIcon(SpriteID.LunarMagicOn.VENGEANCE);

        change(VarbitID.VENGEANCE_REBOUND, 0);
        assertTrue(state.ready);
        assertIcon(SpriteID.LunarMagicOn.VENGEANCE_OTHER);
        assertTrue(manager.shouldRender(state, now, true));

        vengeance.reset();
        manager.reset();
        manager.update(++now);
        assertFalse(manager.shouldRender(state, now, true));
    }

    private void change(int varbit, int value) {
        VarbitChanged event = new VarbitChanged();
        event.setVarbitId(varbit);
        event.setValue(value);
        vengeance.onVarbitChanged(event);
        now += TimeConstants.secondsToNanos(1);
        manager.update(now);
    }

    private void assertIcon(int spriteId) {
        IconRef icon = manager.iconFor(display);
        assertEquals(IconGroup.SPELL, icon.group);
        assertEquals(spriteId, icon.id);
    }
}

package com.pvmhud.overlay;

import com.pvmhud.PvMHUDConfig;
import org.junit.Test;

import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;

import static org.junit.Assert.assertTrue;

public class HudTextRendererTest {
    @Test
    public void centeredTextUsesConfiguredOutline() {
        Color outline = new Color(12, 34, 56);
        PvMHUDConfig config = new PvMHUDConfig() {
            @Override
            public boolean textOutline() {
                return true;
            }

            @Override
            public Color outlineColor() {
                return outline;
            }
        };
        HudTextRenderer renderer = new HudTextRenderer(config);

        BufferedImage image = new BufferedImage(100, 40, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        try {
            graphics.setColor(Color.WHITE);
            FontMetrics metrics = graphics.getFontMetrics();
            renderer.drawCenteredText(graphics, metrics, "42", 0, 0, 100, 40);
        } finally {
            graphics.dispose();
        }

        boolean foundOutlinePixel = false;
        for (int y = 0; y < image.getHeight() && !foundOutlinePixel; y++) {
            for (int x = 0; x < image.getWidth(); x++) {
                if (image.getRGB(x, y) == outline.getRGB()) {
                    foundOutlinePixel = true;
                    break;
                }
            }
        }

        assertTrue("centered text should use the configured outline", foundOutlinePixel);
    }
}

package com.pvmhud.overlay;

import com.pvmhud.PvMHUDConfig;
import org.junit.Test;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class TextIconHudRendererTest {
    @Test
    public void textStyleIgnoresIconSizesInBothLayouts() {
        HudFrame frame = new HudFrame(
                List.of(new Segment(SegmentKind.STAT, "H 99", "99", Color.RED, null)),
                List.of(new Segment(SegmentKind.SPELL, "V", "", Color.BLUE, null)),
                List.of(new Segment(SegmentKind.HEART, "Heart", "", Color.GREEN, null))
        );

        for (boolean vertical : new boolean[]{false, true}) {
            PvMHUDConfig config = new PvMHUDConfig() {
                @Override
                public boolean verticalLayout() {
                    return vertical;
                }

                @Override
                public boolean showIcons() {
                    return true;
                }

                @Override
                public int statIconSize() {
                    return 32;
                }

                @Override
                public int spellIconSize() {
                    return 32;
                }
            };
            TextIconHudRenderer renderer = new TextIconHudRenderer();
            renderer.config = config;
            renderer.text = new HudTextRenderer(config);

            Graphics2D graphics = new BufferedImage(300, 200, BufferedImage.TYPE_INT_ARGB).createGraphics();
            try {
                FontMetrics metrics = graphics.getFontMetrics();
                Dimension bounds = renderer.render(graphics, metrics, frame, false);
                int expectedHeight = 3 * metrics.getHeight() + 2 * config.rowGap() + 2 * HudConstants.PADDING_Y;
                assertEquals("Text style must not reserve space for invisible icons", expectedHeight, bounds.height);
            } finally {
                graphics.dispose();
            }
        }
    }

    @Test
    public void horizontalHeartRemainsInsideBoundsWhenStatsAreHidden() {
        PvMHUDConfig config = new PvMHUDConfig() {
            @Override
            public boolean verticalLayout() {
                return false;
            }

            @Override
            public boolean showIcons() {
                return false;
            }

            @Override
            public int rowGap() {
                return 3;
            }

            @Override
            public boolean textOutline() {
                return false;
            }

            @Override
            public boolean textShadow() {
                return false;
            }
        };

        TextIconHudRenderer renderer = new TextIconHudRenderer();
        renderer.config = config;
        renderer.text = new HudTextRenderer(config);

        HudFrame frame = new HudFrame(
                List.of(),
                List.of(new Segment(SegmentKind.SPELL, "Spell", "", Color.BLUE, null)),
                List.of(new Segment(SegmentKind.HEART, "Heart", "", Color.RED, null))
        );

        BufferedImage image = new BufferedImage(300, 200, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        Dimension bounds;
        try {
            FontMetrics metrics = graphics.getFontMetrics();
            bounds = renderer.render(graphics, metrics, frame, false);
        } finally {
            graphics.dispose();
        }

        int lastPaintedRow = -1;
        for (int y = 0; y < image.getHeight(); y++) {
            for (int x = 0; x < image.getWidth(); x++) {
                if ((image.getRGB(x, y) >>> 24) != 0) {
                    lastPaintedRow = y;
                }
            }
        }

        assertTrue(lastPaintedRow >= 0);
        assertTrue("painted content must fit the returned overlay bounds", lastPaintedRow < bounds.height);
    }
}

package com.pvmhud.overlay;

import com.pvmhud.PvMHUDConfig;
import com.pvmhud.tracking.CorruptionTracker;
import com.pvmhud.tracking.DeathChargeTracker;
import com.pvmhud.tracking.HeartTracker;
import com.pvmhud.tracking.MarkOfDarknessTracker;
import com.pvmhud.tracking.ThrallTracker;
import com.pvmhud.tracking.VengeanceTracker;
import com.pvmhud.tracking.WardOfArceuusTracker;
import org.junit.Test;

import java.awt.Color;

import static org.junit.Assert.assertEquals;

public class HudVisualStateManagerTest {
    @Test
    public void cooldownOnlyTrackersUseTheirConfiguredColors() {
        Color corruptionColor = new Color(1, 2, 3);
        Color heartColor = new Color(4, 5, 6);
        PvMHUDConfig config = new PvMHUDConfig() {
            @Override
            public Color corruptionActiveColor() {
                return corruptionColor;
            }

            @Override
            public Color heartActiveColor() {
                return heartColor;
            }
        };

        ThrallTracker thrall = new ThrallTracker();
        VengeanceTracker vengeance = new VengeanceTracker();
        DeathChargeTracker deathCharge = new DeathChargeTracker();
        MarkOfDarknessTracker markOfDarkness = new MarkOfDarknessTracker();
        CorruptionTracker corruption = new CorruptionTracker();
        WardOfArceuusTracker ward = new WardOfArceuusTracker();
        HeartTracker heart = new HeartTracker();
        HudVisualStateManager manager = new HudVisualStateManager(
                config,
                thrall,
                vengeance,
                deathCharge,
                markOfDarkness,
                corruption,
                ward,
                heart
        );
        VisualState cooldown = new VisualState();
        cooldown.ready = false;
        cooldown.cooldown = true;

        assertEquals(corruptionColor, manager.colorFor(corruption, cooldown, 0L));
        assertEquals(heartColor, manager.colorFor(heart, cooldown, 0L));
    }
}

package com.pvmhud.alerts;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class OverheadAlertManagerTest {
    @Test
    public void downwardCrossingOnlyFiresWhenThresholdIsCrossed() {
        assertTrue(OverheadAlertManager.crossedDown(46, 45, 45));
        assertFalse(OverheadAlertManager.crossedDown(45, 44, 45));
        assertFalse(OverheadAlertManager.crossedDown(46, 46, 45));
    }

    @Test
    public void upwardCrossingOnlyFiresWhenThresholdIsCrossed() {
        assertTrue(OverheadAlertManager.crossedUp(49, 50, 50));
        assertFalse(OverheadAlertManager.crossedUp(50, 60, 50));
        assertFalse(OverheadAlertManager.crossedUp(49, 49, 50));
    }

    @Test
    public void largeSpecRestoresRequireCombatContext() {
        assertTrue(OverheadAlertManager.isAlertableSpecRestore(10, false));
        assertFalse(OverheadAlertManager.isAlertableSpecRestore(50, false));
        assertTrue(OverheadAlertManager.isAlertableSpecRestore(50, true));
        assertFalse(OverheadAlertManager.isAlertableSpecRestore(0, true));
    }
}

package com.pvmhud.alerts;

import org.junit.Test;

import java.util.concurrent.atomic.AtomicBoolean;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class SpellExpiryAlertManagerTest {
    @Test
    public void alertsOnlyOnEnabledTrueToFalseTransition() {
        AtomicBoolean enabled = new AtomicBoolean(true);
        AtomicBoolean active = new AtomicBoolean(true);
        SpellExpiryAlertManager.TrackedState state = new SpellExpiryAlertManager.TrackedState(
                enabled::get,
                active::get,
                () -> "ended"
        );

        assertFalse(state.update());
        assertFalse(state.update());

        active.set(false);
        assertTrue(state.update());
        assertFalse(state.update());

        enabled.set(false);
        assertFalse(state.update());
        active.set(true);
        enabled.set(true);
        assertFalse(state.update());
    }
}

package com.pvmhud.alerts;

import org.junit.Test;

import java.awt.Color;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class OverheadAlertBatchTest {
    @Test
    public void combinesStatSpecAndSpellAlertsWithIndependentColors() {
        OverheadAlertBatch batch = new OverheadAlertBatch();
        batch.add("Low HP!", Color.RED);
        batch.add("Low Prayer!", Color.BLUE);
        batch.add("Spec!", Color.YELLOW);
        batch.add("Vengeance ended!", Color.GREEN);

        assertEquals("<col=ff0000>Low HP!</col> | <col=0000ff>Low Prayer!</col>"
                + " | <col=ffff00>Spec!</col> | <col=00ff00>Vengeance ended!</col>", batch.drain());
        assertTrue(batch.isEmpty());
        assertEquals("", batch.drain());
    }

    @Test
    public void deduplicatesWithinOneBatchButAllowsTheNextAlert() {
        OverheadAlertBatch batch = new OverheadAlertBatch();
        batch.add(" Spec! ", Color.YELLOW);
        batch.add("Spec!", Color.YELLOW);
        assertEquals("<col=ffff00>Spec!</col>", batch.drain());

        batch.add("Spec!", Color.YELLOW);
        assertEquals("<col=ffff00>Spec!</col>", batch.drain());
    }

    @Test
    public void ignoresBlankAlertsAndDefaultsMissingColorToWhite() {
        OverheadAlertBatch batch = new OverheadAlertBatch();
        batch.add(null, Color.RED);
        batch.add(" \t ", Color.RED);
        assertTrue(batch.isEmpty());

        batch.add(" Low HP! ", null);
        assertEquals("<col=ffffff>Low HP!</col>", batch.drain());
    }

    @Test
    public void resetDiscardsPendingAlerts() {
        OverheadAlertBatch batch = new OverheadAlertBatch();
        batch.add("Low Prayer!", Color.BLUE);
        batch.clear();
        batch.add("Spec!", Color.YELLOW);

        assertEquals("<col=ffff00>Spec!</col>", batch.drain());
    }
}

package com.pvmhud.tracking;

import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class DeathChargeTrackerTest {
    @Test
    public void yamaChargeTransitionKeepsTimerAndUpdatesCount() {
        DeathChargeTracker tracker = new DeathChargeTracker();

        tracker.onVarbitChanged(activeStateChanged(2));
        assertTrue(tracker.isActive());
        assertEquals("2", tracker.getBadgeText());

        tracker.onVarbitChanged(activeStateChanged(1));
        assertTrue(tracker.isActive());
        assertEquals("1", tracker.getBadgeText());

        tracker.onVarbitChanged(activeStateChanged(0));
        assertEquals("", tracker.getBadgeText());
        assertTrue(tracker.getProgress() > 0d);
    }

    @Test
    public void restoredActiveStateDoesNotInventFreshDuration() {
        DeathChargeTracker tracker = new DeathChargeTracker();

        tracker.restoreFromClientState(1, 1);

        assertTrue(tracker.isActive());
        assertEquals("1", tracker.getBadgeText());
        assertEquals("", tracker.getDisplayText());
        assertEquals(-1d, tracker.getProgress(), 0d);

        tracker.restoreFromClientState(1, 0);
        assertFalse(tracker.hasActiveEffect());
    }

    private static VarbitChanged activeStateChanged(int value) {
        VarbitChanged event = new VarbitChanged();
        event.setVarbitId(VarbitID.ARCEUUS_DEATH_CHARGE_ACTIVE);
        event.setValue(value);
        return event;
    }
}

package com.pvmhud.tracking;

import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class MarkOfDarknessTrackerTest {
    private static final String PLACED = "You have placed a Mark of Darkness upon yourself.";
    private static final String EXPIRING = "Your Mark of Darkness is about to run out.";
    private static final String FADED = "Your Mark of Darkness has faded away.";
    private static final String[] FORMATS = {
            "%s",
            "<col=6800bf>%s</col>",
            "@mes_hl_pur@%s</col>"
    };

    @Test
    public void tracksActivationWarningAndExpiryAcrossMessageFormats() {
        for (String format : FORMATS) {
            MarkOfDarknessTracker tracker = new TestTracker();

            tracker.onChatMessage(gameMessage(String.format(format, PLACED)));
            assertTrue(format, tracker.isActive());
            assertTrue(format, tracker.getProgress() > 0d);
            assertFalse(format, tracker.isExpiringSoon(0));

            tracker.onChatMessage(gameMessage(String.format(format, EXPIRING)));
            assertTrue(format, tracker.isActive());
            assertTrue(format, tracker.isExpiringSoon(0));

            tracker.onChatMessage(gameMessage(String.format(format, FADED)));
            assertFalse(format, tracker.hasActiveEffect());
            assertFalse(format, tracker.isExpiringSoon(0));
            assertEquals(format, "", tracker.getDisplayText());
        }
    }

    @Test
    public void recastingClearsThePreviousWarning() {
        MarkOfDarknessTracker tracker = new TestTracker();
        tracker.onChatMessage(gameMessage("@mes_hl_pur@" + PLACED + "</col>"));
        tracker.onChatMessage(gameMessage("@mes_hl_pur@" + EXPIRING + "</col>"));
        assertTrue(tracker.isExpiringSoon(0));

        tracker.onChatMessage(gameMessage("@mes_hl_pur@" + PLACED + "</col>"));

        assertTrue(tracker.isActive());
        assertFalse(tracker.isExpiringSoon(0));
    }

    @Test
    public void ignoresUnrelatedMessagesAndNonGameMessages() {
        MarkOfDarknessTracker tracker = new TestTracker();
        tracker.onChatMessage(new ChatMessage(null, ChatMessageType.PUBLICCHAT, "", PLACED, "", 0));
        tracker.onChatMessage(gameMessage("Your defence against Arceuus magic has been strengthened."));
        tracker.onChatMessage(gameMessage(PLACED + " This is not the cast message."));
        assertFalse(tracker.isActive());

        tracker.onChatMessage(gameMessage(PLACED));
        tracker.onChatMessage(new ChatMessage(null, ChatMessageType.PUBLICCHAT, "", EXPIRING, "", 0));
        tracker.onChatMessage(new ChatMessage(null, ChatMessageType.PUBLICCHAT, "", FADED, "", 0));
        tracker.onChatMessage(gameMessage("Your Ward of Arceuus has expired."));
        assertTrue(tracker.isActive());
        assertFalse(tracker.isExpiringSoon(0));
    }

    @Test
    public void warningAndExpiryCannotActivateAnUntrackedMark() {
        MarkOfDarknessTracker tracker = new TestTracker();

        tracker.onChatMessage(gameMessage("@mes_hl_pur@" + EXPIRING + "</col>"));
        assertFalse(tracker.isActive());
        assertFalse(tracker.isExpiringSoon(0));

        tracker.onChatMessage(gameMessage("@mes_hl_pur@" + FADED + "</col>"));
        assertFalse(tracker.isActive());
    }

    @Test
    public void durationUsesThreeTicksPerRealMagicLevelAndPurgingStaffMultiplier() {
        assertEquals(183, MarkOfDarknessTracker.estimateDurationTicks(61, false));
        assertEquals(297, MarkOfDarknessTracker.estimateDurationTicks(99, false));
        assertEquals(1485, MarkOfDarknessTracker.estimateDurationTicks(99, true));
    }

    private static ChatMessage gameMessage(String message) {
        return new ChatMessage(null, ChatMessageType.GAMEMESSAGE, "", message, "", 0);
    }

    private static final class TestTracker extends MarkOfDarknessTracker {
        @Override
        int getDurationTicks() {
            return estimateDurationTicks(99, false);
        }
    }
}

package com.pvmhud.tracking;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

