package com.pvmhud.overlay;

import com.pvmhud.PvMHUDConfig;
import net.runelite.client.ui.FontManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.Font;

@Singleton
final class HudFontResolver {
    @Inject
    private PvMHUDConfig config;

    private Font cachedBaseFont;
    private HudFont cachedType;
    private int cachedSize;
    private boolean cachedBold;
    private Font cachedFont;

    Font resolve(Font baseFont) {
        HudFont type = config.fontType();
        int size = config.fontSize();
        boolean bold = config.boldFont();
        if (cachedFont != null && cachedBaseFont.equals(baseFont) && cachedType == type
                && cachedSize == size && cachedBold == bold) {
            return cachedFont;
        }

        Font resolved;
        switch (type) {
            case RUNESCAPE:
                resolved = FontManager.getRunescapeFont().deriveFont((float) size);
                break;
            case RUNESCAPE_BOLD:
                resolved = FontManager.getRunescapeBoldFont().deriveFont((float) size);
                break;
            case RUNESCAPE_SMALL:
                resolved = FontManager.getRunescapeSmallFont().deriveFont((float) size);
                break;
            case SYSTEM:
            default:
                resolved = baseFont.deriveFont(bold ? Font.BOLD : Font.PLAIN, (float) size);
                break;
        }

        cachedBaseFont = baseFont;
        cachedType = type;
        cachedSize = size;
        cachedBold = bold;
        cachedFont = resolved;
        return resolved;
    }
}

package com.pvmhud.overlay;

final class VisualState {
    boolean initialised;
    boolean active;
    boolean cooldown;
    boolean ready = true;
    boolean expiringSoon;
    long lastVisibleNanos;
    long lastTransitionNanos;

    void reset() {
        initialised = false;
        active = false;
        cooldown = false;
        ready = true;
        expiringSoon = false;
        lastVisibleNanos = 0L;
        lastTransitionNanos = 0L;
    }
}

package com.pvmhud.overlay;

import com.pvmhud.PvMHUDConfig;
import com.pvmhud.tracking.CorruptionTracker;
import com.pvmhud.tracking.DeathChargeTracker;
import com.pvmhud.tracking.HeartTracker;
import com.pvmhud.tracking.MarkOfDarknessTracker;
import com.pvmhud.tracking.SpellStateTracker;
import com.pvmhud.tracking.ThrallTracker;
import com.pvmhud.tracking.TimeConstants;
import com.pvmhud.tracking.VengeanceTracker;
import com.pvmhud.tracking.WardOfArceuusTracker;
import net.runelite.api.gameval.SpriteID;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.Color;
import java.util.List;

@Singleton
final class HudVisualStateManager {
    private static final IconRef INACTIVE_VENGEANCE_ICON = IconRef.spell(SpriteID.LunarMagicOn.VENGEANCE_OTHER);

    private final PvMHUDConfig config;
    private final ThrallTracker thrallTracker;
    private final VengeanceTracker vengeanceTracker;
    private final DeathChargeTracker deathChargeTracker;
    private final MarkOfDarknessTracker markOfDarknessTracker;
    private final CorruptionTracker corruptionTracker;
    private final WardOfArceuusTracker wardOfArceuusTracker;
    private final HeartTracker heartTracker;

    private final List<TrackerDisplay> trackerDisplays;
    private final VisualState heartVisualState = new VisualState();

    @Inject
    HudVisualStateManager(
            PvMHUDConfig config,
            ThrallTracker thrallTracker,
            VengeanceTracker vengeanceTracker,
            DeathChargeTracker deathChargeTracker,
            MarkOfDarknessTracker markOfDarknessTracker,
            CorruptionTracker corruptionTracker,
            WardOfArceuusTracker wardOfArceuusTracker,
            HeartTracker heartTracker
    ) {
        this.config = config;
        this.thrallTracker = thrallTracker;
        this.vengeanceTracker = vengeanceTracker;
        this.deathChargeTracker = deathChargeTracker;
        this.markOfDarknessTracker = markOfDarknessTracker;
        this.corruptionTracker = corruptionTracker;
        this.wardOfArceuusTracker = wardOfArceuusTracker;
        this.heartTracker = heartTracker;

        trackerDisplays = List.of(
                new TrackerDisplay(thrallTracker, "T", IconRef.spell(SpriteID.MagicNecroOn.RESURRECT_SUPERIOR_SKELETON), config::showThrall),
                new TrackerDisplay(deathChargeTracker, "D", IconRef.spell(SpriteID.MagicNecroOn.DEATH_CHARGE), config::showDeathCharge),
                new TrackerDisplay(markOfDarknessTracker, "M", IconRef.spell(SpriteID.MagicNecroOn.MARK_OF_DARKNESS), config::showMarkOfDarkness),
                new TrackerDisplay(vengeanceTracker, "V", IconRef.spell(SpriteID.LunarMagicOn.VENGEANCE), config::showVengeance),
                new TrackerDisplay(corruptionTracker, "C", IconRef.spell(SpriteID.MagicNecroOn.GREATER_CORRUPTION), config::showCorruption),
                new TrackerDisplay(wardOfArceuusTracker, "W", IconRef.spell(SpriteID.MagicNecroOn.WARD_OF_ARCEUUS), config::showWardOfArceuus)
        );
    }

    List<TrackerDisplay> displays() {
        return trackerDisplays;
    }

    VisualState heartState() {
        return heartVisualState;
    }

    HeartTracker heartTracker() {
        return heartTracker;
    }

    void update(long now) {
        for (TrackerDisplay display : trackerDisplays) {
            updateVisualState(display.tracker, display.state, now);
        }

        updateVisualState(heartTracker, heartVisualState, now);
    }

    void reset() {
        for (TrackerDisplay display : trackerDisplays) {
            display.state.reset();
        }
        heartVisualState.reset();
    }

    boolean shouldRender(VisualState state, long now, boolean allowInactive) {
        if (!state.ready) {
            return true;
        }

        return allowInactive
                && config.inactiveSpellTimeoutSeconds() > 0
                && state.lastVisibleNanos > 0L
                && now - state.lastVisibleNanos <= TimeConstants.secondsToNanos(config.inactiveSpellTimeoutSeconds());
    }

    Color colorFor(SpellStateTracker tracker, VisualState state, long now) {
        if (state.expiringSoon) {
            return config.expiringSpellColor();
        }

        if (state.active) {
            return activeColor(tracker);
        }

        if (state.cooldown) {
            if (tracker == deathChargeTracker) {
                return config.deathChargeCooldownColor();
            }
            if (tracker == corruptionTracker || tracker == heartTracker) {
                return activeColor(tracker);
            }
            return config.cooldownSpellColor();
        }

        if (shouldFlashReady(state, now)) {
            return config.readySpellFlashColor();
        }

        return config.readySpellColor();
    }

    IconRef iconFor(TrackerDisplay display) {
        if (display.tracker == vengeanceTracker && !display.state.active) {
            return INACTIVE_VENGEANCE_ICON;
        }
        return display.icon;
    }

    private void updateVisualState(SpellStateTracker tracker, VisualState state, long now) {
        boolean active = tracker.isActive();
        boolean cooldown = !active && tracker.isOnCooldown();
        boolean ready = !active && !cooldown;
        boolean expiringSoon = tracker.isExpiringSoon(config.spellExpiringSoonSeconds());

        if (state.initialised && state.ready != ready) {
            state.lastTransitionNanos = now;
        }
        state.initialised = true;

        if (!ready) {
            state.lastVisibleNanos = now;
        }

        state.active = active;
        state.cooldown = cooldown;
        state.ready = ready;
        state.expiringSoon = expiringSoon;

        if (ready && state.lastTransitionNanos > 0L && config.readySpellFlashRecentSeconds() > 0) {
            long flashWindowNanos = TimeConstants.secondsToNanos(config.readySpellFlashRecentSeconds());
            if (now - state.lastTransitionNanos > flashWindowNanos) {
                state.lastTransitionNanos = 0L;
            }
        }
    }

    private boolean shouldFlashReady(VisualState state, long now) {
        if (!config.flashReadySpells()) {
            return false;
        }

        int windowSeconds = config.readySpellFlashRecentSeconds();
        if (windowSeconds == 0) {
            return isFlashPhase(now);
        }

        return state.lastTransitionNanos > 0L
                && now - state.lastTransitionNanos <= TimeConstants.secondsToNanos(windowSeconds)
                && isFlashPhase(now);
    }

    private boolean isFlashPhase(long now) {
        long period = Math.max(100L, config.flashPeriodMillis()) * TimeConstants.NS_PER_MS;
        return (now / period) % 2L == 0L;
    }

    private Color activeColor(SpellStateTracker tracker) {
        if (tracker == thrallTracker) {
            return config.thrallActiveColor();
        }
        if (tracker == markOfDarknessTracker) {
            return config.markOfDarknessActiveColor();
        }
        if (tracker == deathChargeTracker) {
            return config.deathChargeActiveColor();
        }
        if (tracker == vengeanceTracker) {
            return config.vengeanceActiveColor();
        }
        if (tracker == corruptionTracker) {
            return config.corruptionActiveColor();
        }
        if (tracker == wardOfArceuusTracker) {
            return config.wardOfArceuusActiveColor();
        }
        if (tracker == heartTracker) {
            return config.heartActiveColor();
        }

        return config.readySpellColor();
    }
}

package com.pvmhud.overlay;

import com.pvmhud.PvMHUDConfig;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.HashMap;
import java.util.Map;

@Singleton
final class HudTextRenderer {
    private static final int MAX_CACHED_COLORS = 128;
    private final PvMHUDConfig config;
    private final Map<Integer, Color> alphaColors = new HashMap<>();

    @Inject
    HudTextRenderer(PvMHUDConfig config) {
        this.config = config;
    }

    void drawText(Graphics2D graphics, String text, int x, int y, Color color) {
        if (text == null || text.isEmpty()) {
            return;
        }

        if (config.textOutline()) {
            graphics.setColor(config.outlineColor());
            graphics.drawString(text, x - 1, y);
            graphics.drawString(text, x + 1, y);
            graphics.drawString(text, x, y - 1);
            graphics.drawString(text, x, y + 1);
        } else if (config.textShadow()) {
            graphics.setColor(config.shadowColor());
            graphics.drawString(text, x + 1, y + 1);
        }

        graphics.setColor(color);
        graphics.drawString(text, x, y);
    }

    void drawCenteredText(Graphics2D graphics, FontMetrics metrics, String text, int x, int y, int width, int height) {
        if (text == null || text.isEmpty()) {
            return;
        }

        int textWidth = metrics.stringWidth(text);
        int textX = x + (width - textWidth) / 2;
        int textY = y + baseline(metrics, height);
        drawText(graphics, text, textX, textY, graphics.getColor());
    }

    void drawBackground(Graphics2D graphics, int width, int height) {
        int alpha = config.backgroundAlpha();
        if (alpha <= 0) {
            return;
        }

        graphics.setColor(withAlpha(config.backgroundColor(), alpha));
        graphics.fillRoundRect(0, 0, width, height, 8, 8);
    }

    int baseline(FontMetrics metrics, int height) {
        return ((height - metrics.getHeight()) / 2) + metrics.getAscent();
    }

    Color withAlpha(Color color, int alpha) {
        Color safeColor = color == null ? Color.BLACK : color;
        int safeAlpha = Math.max(0, Math.min(255, alpha));
        if (safeColor.getAlpha() == safeAlpha) {
            return safeColor;
        }

        int argb = (safeAlpha << 24) | (safeColor.getRGB() & 0xFFFFFF);
        Color cached = alphaColors.get(argb);
        if (cached != null) {
            return cached;
        }

        if (alphaColors.size() >= MAX_CACHED_COLORS) {
            alphaColors.clear();
        }
        Color result = new Color(argb, true);
        alphaColors.put(argb, result);
        return result;
    }
}

package com.pvmhud.overlay;

import javax.inject.Singleton;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.List;

@Singleton
final class BarHudRenderer extends AbstractHudRenderer {
    Dimension render(Graphics2D graphics, FontMetrics metrics, HudFrame frame) {
        List<Segment> spells = frame.spells();
        List<Segment> hearts = frame.hearts();
        int spellCount = spells.size() + hearts.size();
        int gap = barGap();
        int tile = barSpellTileSize();
        int spellTileWidth = spellTileWidth(metrics, spells, hearts, tile);
        int statIconSize = config.showIcons() ? config.statIconSize() : 0;
        int barHeight = config.barHeight();
        int barWidth = config.barWidth();
        int spellWidth = spellCount == 0 ? 0 : spellCount * spellTileWidth + (spellCount - 1) * gap;

        if (config.verticalLayout()) {
            return renderVertical(graphics, metrics, frame, spells, hearts, gap, tile, spellTileWidth);
        }

        int statWidth = frame.stats().isEmpty()
                ? 0
                : statIconSize + (statIconSize > 0 ? iconTextGap() : 0) + barWidth;
        int width = Math.max(spellWidth, statWidth) + HudConstants.PADDING_X * 2;
        int rowHeight = Math.max(statIconSize, barHeight);
        int height = HudConstants.PADDING_Y * 2
                + (spellCount == 0 ? 0 : tile)
                + (spellCount > 0 && !frame.stats().isEmpty() ? gap + 1 : 0)
                + (frame.stats().isEmpty() ? 0 : frame.stats().size() * rowHeight + Math.max(0, frame.stats().size() - 1) * gap);

        text.drawBackground(graphics, width, height);

        int y = HudConstants.PADDING_Y;
        if (spellCount > 0) {
            int x = centeredStartX(width, spellWidth);
            for (Segment segment : spells) {
                drawSpellTile(graphics, segment, x, y, spellTileWidth, tile);
                x += spellTileWidth + gap;
            }
            for (Segment segment : hearts) {
                drawSpellTile(graphics, segment, x, y, spellTileWidth, tile);
                x += spellTileWidth + gap;
            }
            y += tile + gap + 1;
        }

        int statX = centeredStartX(width, statWidth);
        for (Segment segment : frame.stats()) {
            drawHorizontalStatBar(graphics, metrics, segment, statX, y, rowHeight);
            y += rowHeight + gap;
        }

        return new Dimension(width, height);
    }

    private Dimension renderVertical(Graphics2D graphics, FontMetrics metrics, HudFrame frame, List<Segment> spells, List<Segment> hearts, int gap, int tile, int spellTileWidth) {
        int statIconSize = config.showIcons() ? config.statIconSize() : 0;
        int barWidth = Math.max(1, config.verticalBarWidth());
        int verticalBarHeight = config.verticalBarHeight();
        int statColumnWidth = frame.stats().isEmpty()
                ? 0
                : frame.stats().size() * Math.max(statIconSize, barWidth) + Math.max(0, frame.stats().size() - 1) * gap;
        int spellCount = spells.size() + hearts.size();
        int spellHeight = spellCount == 0 ? 0 : spellCount * tile + Math.max(0, spellCount - 1) * gap;
        int statHeight = frame.stats().isEmpty()
                ? 0
                : statIconSize + (statIconSize > 0 ? iconTextGap() : 0) + verticalBarHeight;
        int columnGap = spellCount > 0 && !frame.stats().isEmpty() ? gap + 2 : 0;

        int width = (spellCount == 0 ? 0 : spellTileWidth) + columnGap + statColumnWidth + HudConstants.PADDING_X * 2;
        int height = Math.max(spellHeight, statHeight) + HudConstants.PADDING_Y * 2;
        text.drawBackground(graphics, width, height);

        int spellY = HudConstants.PADDING_Y + Math.max(0, (height - HudConstants.PADDING_Y * 2 - spellHeight) / 2);
        for (Segment segment : spells) {
            drawSpellTile(graphics, segment, HudConstants.PADDING_X, spellY, spellTileWidth, tile);
            spellY += tile + gap;
        }
        for (Segment segment : hearts) {
            drawSpellTile(graphics, segment, HudConstants.PADDING_X, spellY, spellTileWidth, tile);
            spellY += tile + gap;
        }

        int x = HudConstants.PADDING_X + (spellCount == 0 ? 0 : spellTileWidth + columnGap);
        int y = HudConstants.PADDING_Y + Math.max(0, (height - HudConstants.PADDING_Y * 2 - statHeight) / 2);
        for (Segment segment : frame.stats()) {
            int columnWidth = Math.max(statIconSize, barWidth);
            drawVerticalStatBar(graphics, metrics, segment, x, y, columnWidth);
            x += columnWidth + gap;
        }

        return new Dimension(width, height);
    }

    private void drawHorizontalStatBar(Graphics2D graphics, FontMetrics metrics, Segment segment, int x, int y, int height) {
        int iconSize = config.showIcons() ? config.statIconSize() : 0;
        BufferedImage icon = icons.load(segment.icon, iconSize);
        if (icon != null) {
            graphics.drawImage(icon, x, y + (height - iconSize) / 2, null);
        }

        int barX = x + iconSize + (iconSize > 0 ? iconTextGap() : 0);
        int barY = y + Math.max(0, (height - config.barHeight()) / 2);
        int barWidth = config.barWidth();
        int barHeight = config.barHeight();

        graphics.setColor(text.withAlpha(config.backgroundColor(), Math.max(40, config.backgroundAlpha())));
        graphics.fillRoundRect(barX, barY, barWidth, barHeight, 5, 5);
        graphics.setColor(text.withAlpha(segment.color, 180));
        int fillWidth = filledLength(barWidth, segment.progress);
        if (fillWidth > 0) {
            graphics.fillRoundRect(barX, barY, fillWidth, barHeight, 5, 5);
        }
        graphics.setColor(Color.WHITE);
        text.drawCenteredText(graphics, metrics, segment.label(), barX, barY, barWidth, barHeight);
    }

    private void drawVerticalStatBar(Graphics2D graphics, FontMetrics metrics, Segment segment, int x, int y, int width) {
        int iconSize = config.showIcons() ? config.statIconSize() : 0;
        BufferedImage icon = icons.load(segment.icon, iconSize);
        if (icon != null) {
            graphics.drawImage(icon, x + (width - iconSize) / 2, y, null);
        }

        int barY = y + iconSize + (iconSize > 0 ? iconTextGap() : 0);
        int barHeight = config.verticalBarHeight();
        int barWidth = Math.max(1, config.verticalBarWidth());
        int barX = x + (width - barWidth) / 2;

        graphics.setColor(text.withAlpha(config.backgroundColor(), Math.max(40, config.backgroundAlpha())));
        graphics.fillRoundRect(barX, barY, barWidth, barHeight, 5, 5);
        graphics.setColor(text.withAlpha(segment.color, 180));
        int fillHeight = filledLength(barHeight, segment.progress);
        if (fillHeight > 0) {
            graphics.fillRoundRect(barX, barY + barHeight - fillHeight, barWidth, fillHeight, 5, 5);
        }

        if (config.verticalBarText()) {
            graphics.setColor(Color.WHITE);
            text.drawCenteredText(graphics, metrics, segment.label(), x, barY, width, barHeight);
        }
    }

    private int barSpellTileSize() {
        return Math.max(14, config.barSpellTileSize());
    }

    static int filledLength(int length, double progress) {
        double safeProgress = Math.max(0d, Math.min(1d, progress));
        return (int) Math.round(Math.max(0, length) * safeProgress);
    }

    private int spellTileWidth(FontMetrics metrics, List<Segment> spells, List<Segment> hearts, int tile) {
        int width = tile;
        for (Segment segment : spells) {
            width = Math.max(width, tileWidth(metrics, segment, tile));
        }
        for (Segment segment : hearts) {
            width = Math.max(width, tileWidth(metrics, segment, tile));
        }
        return width;
    }

    private int tileWidth(FontMetrics metrics, Segment segment, int tile) {
        String label = config.showIcons() ? segment.label() : segment.text;
        return label.isEmpty()
                ? tile
                : (config.showIcons() ? tile + iconTextGap() : 0) + metrics.stringWidth(label) + 4;
    }
}

