@Singleton
final class ChipHudRenderer extends AbstractHudRenderer {
    private static final int PROGRESS_HEIGHT = 2;

    private Font counterSourceFont;
    private Font counterFont;

    Dimension render(Graphics2D graphics, FontMetrics metrics, HudFrame frame) {
        List<Segment> spells = frame.spells();
        List<Segment> hearts = frame.hearts();
        int spellCount = spells.size() + hearts.size();
        int itemGap = groupGap();
        int lineGap = rowGap();
        int chipHeight = chipHeight(metrics);

        if (config.verticalLayout()) {
            int total = frame.stats().size() + spellCount;
            int width = maxChipWidth(metrics, frame.stats(), spells, hearts) + HudConstants.PADDING_X * 2;
            int height = total * chipHeight + Math.max(0, total - 1) * lineGap + HudConstants.PADDING_Y * 2;

            text.drawBackground(graphics, width, height);

            int y = HudConstants.PADDING_Y;
            for (Segment segment : frame.stats()) {
                drawChip(graphics, metrics, segment, HudConstants.PADDING_X, y, width - HudConstants.PADDING_X * 2, chipHeight);
                y += chipHeight + lineGap;
            }
            for (Segment segment : spells) {
                drawChip(graphics, metrics, segment, HudConstants.PADDING_X, y, width - HudConstants.PADDING_X * 2, chipHeight);
                y += chipHeight + lineGap;
            }
            for (Segment segment : hearts) {
                drawChip(graphics, metrics, segment, HudConstants.PADDING_X, y, width - HudConstants.PADDING_X * 2, chipHeight);
                y += chipHeight + lineGap;
            }
            return new Dimension(width, height);
        }

        int spellWidth = chipsWidth(metrics, spells, hearts, itemGap);
        int statWidth = chipsWidth(metrics, frame.stats(), itemGap);
        int width = Math.max(statWidth, spellWidth) + HudConstants.PADDING_X * 2;
        int rows = (frame.stats().isEmpty() ? 0 : 1) + (spellCount == 0 ? 0 : 1);
        int height = rows * chipHeight + Math.max(0, rows - 1) * lineGap + HudConstants.PADDING_Y * 2;

        text.drawBackground(graphics, width, height);

        int y = HudConstants.PADDING_Y;
        if (spellCount > 0) {
            drawChipRows(graphics, metrics, spells, hearts, y, width, spellWidth, itemGap, chipHeight);
            y += chipHeight + lineGap;
        }
        if (!frame.stats().isEmpty()) {
            drawChipRow(graphics, metrics, frame.stats(), y, width, statWidth, itemGap, chipHeight);
        }

        return new Dimension(width, height);
    }

    private void drawChipRow(Graphics2D graphics, FontMetrics metrics, List<Segment> segments, int y, int width, int rowWidth, int gap, int chipHeight) {
        int x = centeredStartX(width, rowWidth);
        for (Segment segment : segments) {
            int chipWidth = chipWidth(metrics, segment);
            drawChip(graphics, metrics, segment, x, y, chipWidth, chipHeight);
            x += chipWidth + gap;
        }
    }

    private void drawChipRows(Graphics2D graphics, FontMetrics metrics, List<Segment> spells, List<Segment> hearts, int y, int width, int rowWidth, int gap, int chipHeight) {
        int x = centeredStartX(width, rowWidth);
        for (Segment segment : spells) {
            int chipWidth = chipWidth(metrics, segment);
            drawChip(graphics, metrics, segment, x, y, chipWidth, chipHeight);
            x += chipWidth + gap;
        }
        for (Segment segment : hearts) {
            int chipWidth = chipWidth(metrics, segment);
            drawChip(graphics, metrics, segment, x, y, chipWidth, chipHeight);
            x += chipWidth + gap;
        }
    }

    private void drawChip(Graphics2D graphics, FontMetrics metrics, Segment segment, int x, int y, int width, int height) {
        int alpha = config.backgroundAlpha();

        if (alpha > 0) {
            graphics.setColor(text.withAlpha(config.backgroundColor(), alpha));
            graphics.fillRoundRect(x, y, width, height, 7, 7);
        }

        graphics.setColor(text.withAlpha(segment.color, Math.max(90, alpha)));
        graphics.drawRoundRect(x, y, width - 1, height - 1, 7, 7);

        if (segment.kind == SegmentKind.STAT) {
            graphics.fillRoundRect(x + 1, y + 1, 3, height - 2, 4, 4);
        }

        int size = iconSize(segment);
        int iconY = y + (height - size) / 2;

        boolean showIcons = config.showIcons();
        String label = !showIcons
                ? segment.text
                : segment.kind == SegmentKind.SPELL ? "" : segment.label();
        boolean hasLabel = !label.isEmpty();
        boolean iconOnly = !hasLabel;

        int iconX;
        int textX = 0;

        if (iconOnly) {
            iconX = x + (width - size) / 2;
        } else {
            int labelWidth = metrics.stringWidth(label);
            int gap = size > 0 ? iconTextGap() : 0;
            int contentWidth = size + gap + labelWidth;

            iconX = x + Math.max(0, (width - contentWidth) / 2);
            textX = iconX + size + gap;
        }

        BufferedImage icon = icons.load(segment.icon, size);
        if (icon != null) {
            graphics.drawImage(icon, iconX, iconY, null);
        }

        if (!iconOnly) {
            text.drawText(graphics, label, textX, y + text.baseline(metrics, height), segment.color);
        }

        if (showIcons && segment.kind == SegmentKind.SPELL && !segment.badgeText.isEmpty()) {
            Graphics2D counterGraphics = (Graphics2D) graphics.create();
            try {
                counterGraphics.setFont(counterFont(graphics.getFont()));
                FontMetrics counterMetrics = counterGraphics.getFontMetrics();
                int countX = x + width - counterMetrics.stringWidth(segment.badgeText) - 3;
                int countBaseline = y + height - PROGRESS_HEIGHT - 3;
                text.drawText(counterGraphics, segment.badgeText, countX, countBaseline, Color.WHITE);
            } finally {
                counterGraphics.dispose();
            }
        }

        drawProgress(graphics, segment, x, y, width, height);
    }

    private void drawProgress(Graphics2D graphics, Segment segment, int x, int y, int width, int height) {
        if (segment.progress < 0d) {
            return;
        }

        int barX = x + 3;
        int barY = y + height - PROGRESS_HEIGHT - 1;
        int barWidth = Math.max(0, width - 6);
        int fillWidth = (int) Math.round(barWidth * Math.max(0d, Math.min(1d, segment.progress)));

        graphics.setColor(text.withAlpha(config.backgroundColor(), 180));
        graphics.fillRect(barX, barY, barWidth, PROGRESS_HEIGHT);
        if (fillWidth > 0) {
            graphics.setColor(text.withAlpha(segment.color, 230));
            graphics.fillRect(barX, barY, fillWidth, PROGRESS_HEIGHT);
        }
    }

    private int chipWidth(FontMetrics metrics, Segment segment) {
        if (segment.kind == SegmentKind.STAT) {
            return config.statChipWidth();
        }

        if (segment.kind == SegmentKind.SPELL || segment.kind == SegmentKind.HEART) {
            return config.showIcons()
                    ? iconSize(segment) + 10
                    : metrics.stringWidth(segment.text) + 14;
        }

        return iconSize(segment) + iconTextGap() + metrics.stringWidth(segment.label()) + 14;
    }

    private int chipsWidth(FontMetrics metrics, List<Segment> spells, List<Segment> hearts, int gap) {
        int count = spells.size() + hearts.size();
        if (count == 0) {
            return 0;
        }

        int width = 0;
        for (Segment segment : spells) {
            width += chipWidth(metrics, segment) + gap;
        }
        for (Segment segment : hearts) {
            width += chipWidth(metrics, segment) + gap;
        }
        return width - gap;
    }

    private int chipsWidth(FontMetrics metrics, List<Segment> segments, int gap) {
        if (segments.isEmpty()) {
            return 0;
        }

        int width = 0;
        for (Segment segment : segments) {
            width += chipWidth(metrics, segment) + gap;
        }
        return width - gap;
    }

    private int maxChipWidth(FontMetrics metrics, List<Segment> stats, List<Segment> spells, List<Segment> hearts) {
        int width = 0;
        for (Segment segment : stats) {
            width = Math.max(width, chipWidth(metrics, segment));
        }
        for (Segment segment : spells) {
            width = Math.max(width, chipWidth(metrics, segment));
        }
        for (Segment segment : hearts) {
            width = Math.max(width, chipWidth(metrics, segment));
        }
        return width;
    }

    private int chipHeight(FontMetrics metrics) {
        int maxIconSize = config.showIcons()
                ? Math.max(config.statIconSize(), config.spellIconSize())
                : 0;
        return Math.max(metrics.getHeight(), maxIconSize) + 6;
    }

    private Font counterFont(Font sourceFont) {
        if (!sourceFont.equals(counterSourceFont)) {
            float size = Math.max(11f, Math.min(14f, sourceFont.getSize2D() * 0.85f));
            counterSourceFont = sourceFont;
            counterFont = sourceFont.deriveFont(Font.BOLD, size);
        }
        return counterFont;
    }
}

package com.pvmhud.overlay;

import net.runelite.api.Skill;

final class IconRef {
    final IconGroup group;
    final int id;

    private IconRef(IconGroup group, int id) {
        this.group = group;
        this.id = id;
    }

    static IconRef statSkill(Skill skill) {
        return new IconRef(IconGroup.STAT, skill.ordinal());
    }

    static IconRef statSprite(int spriteId) {
        return new IconRef(IconGroup.SPRITE, spriteId);
    }

    static IconRef spell(int spriteId) {
        return new IconRef(IconGroup.SPELL, spriteId);
    }

    static IconRef item(int itemId) {
        return new IconRef(IconGroup.ITEM, itemId);
    }

    long cacheKey(int size) {
        return ((long) group.ordinal() << 48) | ((long) id << 16) | size;
    }
}

package com.pvmhud.overlay;

import javax.inject.Singleton;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.List;

@Singleton
final class TextIconHudRenderer extends AbstractHudRenderer {
    Dimension render(Graphics2D graphics, FontMetrics metrics, HudFrame frame, boolean gameIconsMode) {
        gameIconsMode = gameIconsMode && config.showIcons();
        List<Segment> spells = frame.spells();
        List<Segment> stats = frame.stats();
        List<Segment> hearts = frame.hearts();
        int paddingX = HudConstants.PADDING_X;
        int paddingY = HudConstants.PADDING_Y;
        int localRowGap = rowGap();

        if (config.verticalLayout()) {
            int maxWidth = 0;
            int maxHeight = metrics.getHeight();
            int total = 0;

            for (Segment segment : stats) {
                maxWidth = Math.max(maxWidth, segmentWidth(metrics, segment, gameIconsMode));
                maxHeight = Math.max(maxHeight, gameIconsMode ? iconSize(segment) : 0);
                total++;
            }
            for (Segment segment : spells) {
                maxWidth = Math.max(maxWidth, segmentWidth(metrics, segment, gameIconsMode));
                maxHeight = Math.max(maxHeight, gameIconsMode ? iconSize(segment) : 0);
                total++;
            }
            for (Segment segment : hearts) {
                maxWidth = Math.max(maxWidth, segmentWidth(metrics, segment, gameIconsMode));
                maxHeight = Math.max(maxHeight, gameIconsMode ? iconSize(segment) : 0);
                total++;
            }

            int width = maxWidth + paddingX * 2;
            int height = total * maxHeight + Math.max(0, total - 1) * localRowGap + paddingY * 2;

            text.drawBackground(graphics, width, height);

            int y = paddingY;
            y = drawVerticalGroup(graphics, metrics, stats, width, y, maxHeight, gameIconsMode, localRowGap);
            y = drawVerticalGroup(graphics, metrics, spells, width, y, maxHeight, gameIconsMode, localRowGap);
            drawVerticalGroup(graphics, metrics, hearts, width, y, maxHeight, gameIconsMode, localRowGap);

            return new Dimension(width, height);
        }

        int rowCount = (!spells.isEmpty() ? 1 : 0) + (!stats.isEmpty() ? 1 : 0) + (!hearts.isEmpty() ? 1 : 0);
        int[] rowWidths = new int[rowCount];
        int[] rowHeights = new int[rowCount];
        int width = 0;
        int height = paddingY * 2;
        int idx = 0;
        idx = measureRow(metrics, spells, gameIconsMode, rowWidths, rowHeights, idx);
        idx = measureRow(metrics, stats, gameIconsMode, rowWidths, rowHeights, idx);
        measureRow(metrics, hearts, gameIconsMode, rowWidths, rowHeights, idx);

        for (int i = 0; i < rowCount; i++) {
            width = Math.max(width, rowWidths[i]);
            height += rowHeights[i];
        }

        height += Math.max(0, rowCount - 1) * localRowGap;
        width += paddingX * 2;

        text.drawBackground(graphics, width, height);

        int y = paddingY;
        int rowIndex = 0;
        if (!spells.isEmpty()) {
            rowIndex = drawRow(graphics, metrics, spells, gameIconsMode, width, rowWidths, rowHeights, rowIndex, y);
            y += rowHeights[rowIndex - 1] + localRowGap;
        }
        if (!stats.isEmpty()) {
            rowIndex = drawRow(graphics, metrics, stats, gameIconsMode, width, rowWidths, rowHeights, rowIndex, y);
            y += rowHeights[rowIndex - 1] + localRowGap;
        }
        drawRow(graphics, metrics, hearts, gameIconsMode, width, rowWidths, rowHeights, rowIndex, y);

        return new Dimension(width, height);
    }

    private void drawSegment(
            Graphics2D graphics,
            FontMetrics metrics,
            Segment segment,
            int x,
            int y,
            int rowHeight,
            boolean gameIconsMode
    ) {
        if (!gameIconsMode) {
            text.drawText(
                    graphics,
                    segment.text,
                    x,
                    y + text.baseline(metrics, rowHeight),
                    segment.color
            );
            return;
        }

        if ((segment.kind == SegmentKind.SPELL || segment.kind == SegmentKind.HEART)
                && segment.label().isEmpty()) {
            drawIconOnly(graphics, segment, x, y, rowHeight);
            return;
        }

        if (segment.kind == SegmentKind.STAT || segment.kind == SegmentKind.SPELL) {
            drawIconWithValue(graphics, metrics, segment, x, y, rowHeight);
            return;
        }

        text.drawText(
                graphics,
                segment.text,
                x,
                y + text.baseline(metrics, rowHeight),
                segment.color
        );
    }

    private void drawIconWithValue(
            Graphics2D graphics,
            FontMetrics metrics,
            Segment segment,
            int x,
            int y,
            int rowHeight
    ) {
        int size = iconSize(segment);
        BufferedImage icon = icons.load(segment.icon, size);

        int textX = x;

        if (icon != null) {
            graphics.drawImage(icon, x, y + (rowHeight - size) / 2, null);
            textX += size + iconTextGap();
        }

        text.drawText(
                graphics,
                segment.iconText,
                textX,
                y + text.baseline(metrics, rowHeight),
                segment.color
        );
    }

    private int segmentWidth(FontMetrics metrics, Segment segment, boolean gameIconsMode) {
        if (!gameIconsMode) {
            return metrics.stringWidth(segment.text);
        }

        if ((segment.kind == SegmentKind.SPELL || segment.kind == SegmentKind.HEART) && segment.icon != null) {
            return iconSize(segment) + (segment.label().isEmpty()
                    ? 0
                    : iconTextGap() + metrics.stringWidth(segment.label()));
        }

        if (segment.kind == SegmentKind.STAT && segment.icon != null) {
            return iconSize(segment) + iconTextGap() + metrics.stringWidth(segment.iconText);
        }

        return metrics.stringWidth(segment.text);
    }

    private int drawVerticalGroup(
            Graphics2D graphics,
            FontMetrics metrics,
            List<Segment> segments,
            int totalWidth,
            int y,
            int rowHeight,
            boolean gameIconsMode,
            int gap
    ) {
        for (Segment segment : segments) {
            int x = gameIconsMode
                    ? centeredStartX(totalWidth, segmentWidth(metrics, segment, true))
                    : HudConstants.PADDING_X;
            drawSegment(graphics, metrics, segment, x, y, rowHeight, gameIconsMode);
            y += rowHeight + gap;
        }
        return y;
    }

    private int measureRow(
            FontMetrics metrics,
            List<Segment> row,
            boolean gameIconsMode,
            int[] rowWidths,
            int[] rowHeights,
            int index
    ) {
        if (row.isEmpty()) {
            return index;
        }
        int width = 0;
        int height = metrics.getHeight();
        int gap = groupGap();
        for (Segment segment : row) {
            width += segmentWidth(metrics, segment, gameIconsMode) + gap;
            height = Math.max(height, gameIconsMode ? iconSize(segment) : 0);
        }
        rowWidths[index] = width - gap;
        rowHeights[index] = height;
        return index + 1;
    }

    private int drawRow(
            Graphics2D graphics,
            FontMetrics metrics,
            List<Segment> row,
            boolean gameIconsMode,
            int totalWidth,
            int[] rowWidths,
            int[] rowHeights,
            int rowIndex,
            int y
    ) {
        if (row.isEmpty()) {
            return rowIndex;
        }

        int x = centeredStartX(totalWidth, rowWidths[rowIndex]);
        for (Segment segment : row) {
            int segmentWidth = segmentWidth(metrics, segment, gameIconsMode);
            drawSegment(graphics, metrics, segment, x, y, rowHeights[rowIndex], gameIconsMode);
            x += segmentWidth + groupGap();
        }
        return rowIndex + 1;
    }

}

package com.pvmhud.overlay;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Skill;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;

@Singleton
@Slf4j
final class HudIconCache {
    private static final Skill[] SKILLS = Skill.values();

    @Inject
    private ItemManager itemManager;

    @Inject
    private SkillIconManager skillIconManager;

    @Inject
    private SpriteManager spriteManager;

    private final Map<Long, BufferedImage> iconCache = new HashMap<>();
    private long generation;

    BufferedImage load(IconRef iconRef, int size) {
        if (iconRef == null || size <= 0) {
            return null;
        }

        long key = iconRef.cacheKey(size);
        BufferedImage cached = iconCache.get(key);
        if (cached != null) {
            return cached;
        }

        BufferedImage image = loadSource(iconRef);
        if (image == null) {
            return null;
        }

        if (image instanceof AsyncBufferedImage) {
            long loadGeneration = generation;
            ((AsyncBufferedImage) image).onLoaded(() -> {
                if (generation == loadGeneration) {
                    iconCache.put(key, ImageUtil.resizeImage(image, size, size));
                }
            });
        }

        BufferedImage scaled = ImageUtil.resizeImage(image, size, size);
        iconCache.put(key, scaled);
        return scaled;
    }

    void clear() {
        generation++;
        iconCache.clear();
    }

    private BufferedImage loadSource(IconRef iconRef) {
        switch (iconRef.group) {
            case STAT:
                return skillIconManager.getSkillImage(SKILLS[iconRef.id]);
            case SPRITE:
            case SPELL:
                try {
                    return spriteManager.getSprite(iconRef.id, 0);
                } catch (RuntimeException ex) {
                    log.debug("Unable to load HUD sprite {}", iconRef.id, ex);
                    return null;
                }
            case ITEM:
                return itemManager.getImage(iconRef.id);
            default:
                return null;
        }
    }
}

