package com.pvmhud.overlay;

import com.pvmhud.PvMHUDConfig;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;

@Singleton
public class PvMHUDOverlay extends Overlay {
    @Inject
    private Client client;

    @Inject
    private PvMHUDConfig config;

    @Inject
    private HudSegmentBuilder segmentBuilder;

    @Inject
    private HudVisualStateManager visualStateManager;

    @Inject
    private HudIconCache iconCache;

    @Inject
    private HudFontResolver fontResolver;

    @Inject
    private HudStyleRenderer styleRenderer;

    private boolean inCombat;

    public PvMHUDOverlay() {
        setPosition(OverlayPosition.TOP_LEFT);
        setLayer(OverlayLayer.ABOVE_SCENE);
        setDragTargetable(true);
    }

    public void reset() {
        inCombat = false;
        visualStateManager.reset();
        segmentBuilder.reset();
    }

    public void setInCombat(boolean inCombat) {
        this.inCombat = inCombat;
    }

    public void updateFrame(long now) {
        segmentBuilder.update(now, !config.hideOutOfCombat() || inCombat);
    }

    public void clearCachedResources() {
        iconCache.clear();
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (client.getLocalPlayer() == null || (config.hideOutOfCombat() && !inCombat)) {
            return null;
        }

        HudFrame frame = segmentBuilder.currentFrame();
        if (frame.isEmpty()) {
            return null;
        }

        Font oldFont = graphics.getFont();
        try {
            graphics.setFont(fontResolver.resolve(oldFont));
            FontMetrics metrics = graphics.getFontMetrics();
            return styleRenderer.render(graphics, metrics, frame, config.hudStyle());
        } finally {
            graphics.setFont(oldFont);
        }
    }
}

package com.pvmhud.overlay;

import java.awt.Color;

final class Segment {
    final SegmentKind kind;
    final String text;
    final String iconText;
    final Color color;
    final IconRef icon;
    final double progress;
    final String badgeText;

    Segment(SegmentKind kind, String text, String iconText, Color color, IconRef icon) {
        this(kind, text, iconText, color, icon, -1d);
    }

    Segment(SegmentKind kind, String text, String iconText, Color color, IconRef icon, double progress) {
        this(kind, text, iconText, color, icon, progress, "");
    }

    Segment(SegmentKind kind, String text, String iconText, Color color, IconRef icon,
            double progress, String badgeText) {
        this.kind = kind;
        this.text = text == null ? "" : text;
        this.iconText = iconText == null ? "" : iconText;
        this.color = color == null ? Color.WHITE : color;
        this.icon = icon;
        this.progress = progress;
        this.badgeText = badgeText == null ? "" : badgeText;
    }

    String label() {
        if (kind == SegmentKind.SPELL || kind == SegmentKind.HEART) {
            return iconText;
        }

        return iconText.isEmpty() ? text : iconText;
    }
}

