package com.pvmhud.alerts;

import com.pvmhud.PvMHUDConfig;
import com.pvmhud.tracking.CorruptionTracker;
import com.pvmhud.tracking.DeathChargeTracker;
import com.pvmhud.tracking.HeartTracker;
import com.pvmhud.tracking.MarkOfDarknessTracker;
import com.pvmhud.tracking.SpellStateTracker;
import com.pvmhud.tracking.ThrallTracker;
import com.pvmhud.tracking.VengeanceTracker;
import com.pvmhud.tracking.WardOfArceuusTracker;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.List;
import java.util.function.BooleanSupplier;
import java.util.function.Supplier;

@Singleton
public class SpellExpiryAlertManager {
    private final PvMHUDConfig config;
    private final OverheadMessageRenderer renderer;
    private final List<TrackedState> trackedStates;

    @Inject
    SpellExpiryAlertManager(
            PvMHUDConfig config,
            OverheadMessageRenderer renderer,
            ThrallTracker thrall,
            DeathChargeTracker deathCharge,
            MarkOfDarknessTracker markOfDarkness,
            VengeanceTracker vengeance,
            WardOfArceuusTracker wardOfArceuus,
            CorruptionTracker corruption,
            HeartTracker heart
    ) {
        this.config = config;
        this.renderer = renderer;
        trackedStates = List.of(
                ended(thrall, config::overheadThrallExpiryAlert, config::thrallExpiryOverheadMessage),
                ended(deathCharge, config::overheadDeathChargeExpiryAlert, config::deathChargeExpiryOverheadMessage),
                ended(markOfDarkness, config::overheadMarkOfDarknessExpiryAlert, config::markOfDarknessExpiryOverheadMessage),
                ended(vengeance, config::overheadVengeanceExpiryAlert, config::vengeanceExpiryOverheadMessage),
                ended(wardOfArceuus, config::overheadWardExpiryAlert, config::wardExpiryOverheadMessage),
                ready(corruption, config::overheadCorruptionReadyAlert, config::corruptionReadyOverheadMessage),
                ready(heart, config::overheadHeartReadyAlert, config::heartReadyOverheadMessage)
        );
    }

    public void update() {
        if (!config.overheadSpellExpiryAlerts()) {
            reset();
            return;
        }

        for (TrackedState trackedState : trackedStates) {
            if (trackedState.update()) {
                renderer.showLocalMessage(trackedState.message.get(), config.spellExpiryOverheadColor());
            }
        }
    }

    public void reset() {
        for (TrackedState trackedState : trackedStates) {
            trackedState.reset();
        }
    }

    private static TrackedState ended(
            SpellStateTracker tracker,
            BooleanSupplier enabled,
            Supplier<String> message
    ) {
        return new TrackedState(enabled, tracker::hasActiveEffect, message);
    }

    private static TrackedState ready(
            SpellStateTracker tracker,
            BooleanSupplier enabled,
            Supplier<String> message
    ) {
        return new TrackedState(enabled, tracker::isOnCooldown, message);
    }

    static final class TrackedState {
        private final BooleanSupplier enabled;
        private final BooleanSupplier state;
        private final Supplier<String> message;
        private boolean initialized;
        private boolean previous;

        TrackedState(BooleanSupplier enabled, BooleanSupplier state, Supplier<String> message) {
            this.enabled = enabled;
            this.state = state;
            this.message = message;
        }

        boolean update() {
            if (!enabled.getAsBoolean()) {
                reset();
                return false;
            }

            boolean current = state.getAsBoolean();
            if (!initialized) {
                initialized = true;
                previous = current;
                return false;
            }

            boolean ended = previous && !current;
            previous = current;
            return ended;
        }

        void reset() {
            initialized = false;
            previous = false;
        }
    }
}

package com.pvmhud.alerts;

import com.pvmhud.PvMHUDConfig;
import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.Color;

@Singleton
public class OverheadAlertManager {
    // Natural regen is 10%; Death Charge and other effects can produce larger legitimate increments.
    private static final int MAX_EXPECTED_INCREMENTAL_SPEC_RESTORE = 25;

    @Inject
    private PvMHUDConfig config;

    @Inject
    private OverheadAlertState state;

    @Inject
    private OverheadMessageRenderer overheadMessageRenderer;

    public void onStatChanged(StatChanged event) {
        if (state.needsBaseline()) {
            return;
        }

        String message = null;
        Color color = null;

        if (event.getSkill() == Skill.HITPOINTS) {
            int currentHp = event.getBoostedLevel();

            if (config.overheadHpAlertEnabled()
                    && crossedDown(state.getPreviousHitpoints(), currentHp, config.hpLowThreshold())) {
                message = config.lowHpOverheadMessage();
                color = config.hpLowColor();
            }

            state.setPreviousHitpoints(currentHp);
        } else if (event.getSkill() == Skill.PRAYER) {
            int currentPrayer = event.getBoostedLevel();

            if (config.overheadPrayerAlertEnabled()
                    && crossedDown(state.getPreviousPrayer(), currentPrayer, config.prayerLowThreshold())) {
                message = config.lowPrayerOverheadMessage();
                color = config.prayerLowColor();
            }

            state.setPreviousPrayer(currentPrayer);
        }

        if (message != null) {
            overheadMessageRenderer.showLocalMessage(message, color);
        }
    }

    public void onSpecPercentChanged(int currentSpecPercent, boolean hasRecentCombatContext) {
        if (state.needsBaseline()) {
            return;
        }

        int previousSpec = state.getPreviousSpec();
        int specChange = currentSpecPercent - previousSpec;

        if (config.overheadSpecAlertEnabled()
                && isAlertableSpecRestore(specChange, hasRecentCombatContext)
                && crossedUp(previousSpec, currentSpecPercent, config.specThreshold())) {
            overheadMessageRenderer.showLocalMessage(config.specOverheadMessage(), config.specHighColor());
        }

        state.setPreviousSpec(currentSpecPercent);
    }

    static boolean crossedDown(int previousValue, int currentValue, int threshold) {
        return previousValue > threshold && currentValue <= threshold;
    }

    static boolean crossedUp(int previousValue, int currentValue, int threshold) {
        return previousValue < threshold && currentValue >= threshold;
    }

    static boolean isAlertableSpecRestore(int specChange, boolean hasRecentCombatContext) {
        return specChange > 0
                && (specChange <= MAX_EXPECTED_INCREMENTAL_SPEC_RESTORE || hasRecentCombatContext);
    }

}

package com.pvmhud.alerts;

import net.runelite.client.util.ColorUtil;

import java.awt.Color;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.StringJoiner;

/** Alerts collected on the client thread and emitted together at the end of the tick. */
final class OverheadAlertBatch {
    private final Map<String, Color> messages = new LinkedHashMap<>();

    void add(String text, Color color) {
        String trimmed = text == null ? "" : text.trim();
        if (!trimmed.isEmpty()) {
            messages.putIfAbsent(trimmed, color == null ? Color.WHITE : color);
        }
    }

    boolean isEmpty() {
        return messages.isEmpty();
    }

    String drain() {
        StringJoiner combined = new StringJoiner(" | ");
        messages.forEach((text, color) -> combined.add(ColorUtil.wrapWithColorTag(text, color)));
        clear();
        return combined.toString();
    }

    void clear() {
        messages.clear();
    }
}

package com.pvmhud.alerts;

import com.pvmhud.PvMHUDConfig;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.Player;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.Color;

@Singleton
public final class OverheadMessageRenderer {
    private static final int CLIENT_CYCLES_PER_SECOND = 1_000 / Constants.CLIENT_TICK_LENGTH;

    private final Client client;
    private final PvMHUDConfig config;
    private final OverheadAlertBatch pendingMessages = new OverheadAlertBatch();
    private Player messagePlayer;
    private String messageText;

    @Inject
    private OverheadMessageRenderer(Client client, PvMHUDConfig config) {
        this.client = client;
        this.config = config;
    }

    void showLocalMessage(String message, Color color) {
        if (client.getLocalPlayer() != null) {
            pendingMessages.add(message, color);
        }
    }

    public void flush() {
        if (pendingMessages.isEmpty()) {
            return;
        }

        String text = pendingMessages.drain();
        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null) {
            return;
        }

        localPlayer.setOverheadText(text);
        localPlayer.setOverheadCycle(Math.max(1, config.overheadAlertSeconds() * CLIENT_CYCLES_PER_SECOND));
        messagePlayer = localPlayer;
        // Core plugins such as Emojis can replace the text synchronously.
        messageText = localPlayer.getOverheadText();
    }

    public void clear() {
        pendingMessages.clear();
        if (messagePlayer != null && messagePlayer == client.getLocalPlayer()
                && messageText != null && messageText.equals(messagePlayer.getOverheadText())) {
            messagePlayer.setOverheadText("");
            messagePlayer.setOverheadCycle(0);
        }
        messagePlayer = null;
        messageText = null;
    }
}

