package com.pvmhud.tracking;

import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Singleton;

@Singleton
public class DeathChargeTracker extends BaseTimedSpellTracker {
    private static final long DEATH_CHARGE_DURATION_NANOS = TimeConstants.secondsToNanos(60);
    private int activeState;

    @Subscribe
    public void onVarbitChanged(VarbitChanged event) {
        if (event.getVarbitId() == VarbitID.ARCEUUS_DEATH_CHARGE_COOLDOWN) {
            setCooldownActive(event.getValue() > 0);
        } else if (event.getVarbitId() == VarbitID.ARCEUUS_DEATH_CHARGE_ACTIVE) {
            int previousState = activeState;
            activeState = event.getValue();

            if (activeState > previousState) {
                markActive(DEATH_CHARGE_DURATION_NANOS);
            } else if (activeState == 0 && hasUnknownActiveDuration()) {
                clearActive();
            }
        }
    }

    @Override
    public boolean isActive() {
        if (!hasTrackedActiveEffect()) {
            syncIfNeeded();
        }
        return activeState > 0 && super.isActive();
    }

    @Override
    public String getBadgeText() {
        return hasTrackedActiveEffect() && activeState > 0 ? Integer.toString(activeState) : "";
    }

    @Override
    protected void sync() {
        int cooldown = client.getVarbitValue(VarbitID.ARCEUUS_DEATH_CHARGE_COOLDOWN);
        int syncedActiveState = client.getVarbitValue(VarbitID.ARCEUUS_DEATH_CHARGE_ACTIVE);
        restoreFromClientState(cooldown, syncedActiveState);
    }

    void restoreFromClientState(int cooldown, int syncedActiveState) {
        setCooldownActive(cooldown > 0);
        if (syncedActiveState > 0 && !hasTrackedActiveEffect()) {
            markActiveWithoutKnownDuration();
        } else if (syncedActiveState == 0 && hasUnknownActiveDuration()) {
            clearActive();
        }
        activeState = syncedActiveState;
    }

    @Override
    public void reset() {
        activeState = 0;
        super.reset();
    }
}

package com.pvmhud.tracking;

import net.runelite.api.events.VarbitChanged;
import net.runelite.client.eventbus.Subscribe;

public abstract class CooldownVarbitTracker extends CachedVarbitTracker implements SpellStateTracker {
    private int cooldownTicks;

    @Override
    public boolean isActive() {
        return false;
    }

    @Override
    public boolean isOnCooldown() {
        syncIfNeeded();
        return cooldownTicks > 0;
    }

    @Override
    protected void sync() {
        cooldownTicks = client.getVarbitValue(cooldownVarbitId());
    }

    @Subscribe
    public final void onVarbitChanged(VarbitChanged event) {
        if (event.getVarbitId() == cooldownVarbitId()) {
            cooldownTicks = Math.max(0, event.getValue());
        }
    }

    @Override
    public void reset() {
        cooldownTicks = 0;
        invalidateCache();
    }

    protected abstract int cooldownVarbitId();
}

package com.pvmhud.tracking;

import net.runelite.api.ChatMessageType;
import net.runelite.api.Skill;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

import javax.inject.Singleton;

@Singleton
public class WardOfArceuusTracker extends BaseTimedSpellTracker {
    private static final String WARD_EXPIRED_MESSAGE =
            "your ward of arceuus has expired.";

    @Subscribe
    public void onVarbitChanged(VarbitChanged event) {
        if (event.getVarbitId() != VarbitID.ARCEUUS_WARD_COOLDOWN) {
            return;
        }

        int cooldownTicks = event.getValue();
        setCooldownActive(cooldownTicks > 0);

        if (cooldownTicks == 1) {
            markActive(estimateDurationNanos());
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage event) {
        if (event.getType() != ChatMessageType.GAMEMESSAGE) {
            return;
        }

        String message = Text.standardize(event.getMessage());

        if (message.endsWith(WARD_EXPIRED_MESSAGE)) {
            clearActive();
        }
    }

    @Override
    protected void sync() {
        int cooldownTicks = client.getVarbitValue(VarbitID.ARCEUUS_WARD_COOLDOWN);
        setCooldownActive(cooldownTicks > 0);
    }

    private long estimateDurationNanos() {
        return estimateDurationNanos(client.getRealSkillLevel(Skill.MAGIC));
    }

    static long estimateDurationNanos(int realMagicLevel) {
        double seconds = Math.max(0, realMagicLevel) * 0.6d;
        return TimeConstants.secondsToNanos(seconds);
    }
}

package com.pvmhud.tracking;

import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;

abstract class CachedSkillTracker implements ResettableTracker {
    @Inject
    private Client client;

    private final Skill skill;
    private int boostedLevel = -1;

    CachedSkillTracker(Skill skill) {
        this.skill = skill;
    }

    @Subscribe
    public final void onStatChanged(StatChanged event) {
        if (event.getSkill() == skill) {
            boostedLevel = event.getBoostedLevel();
        }
    }

    protected final int getBoostedLevel() {
        if (boostedLevel < 0) {
            boostedLevel = client.getBoostedSkillLevel(skill);
        }
        return boostedLevel;
    }

    @Override
    public final void reset() {
        boostedLevel = -1;
    }
}

package com.pvmhud.tracking;

import net.runelite.api.Skill;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Singleton;

@Singleton
public class ThrallTracker extends BaseTimedSpellTracker {
    private static final int THRALL_SPAWN_DELAY_TICKS = 4;

    @Subscribe
    public void onVarbitChanged(VarbitChanged event) {
        if (event.getVarbitId() == VarbitID.ARCEUUS_RESURRECTION_ACTIVE) {
            updateActiveState(event.getValue());
            return;
        }

        if (event.getVarbitId() != VarbitID.ARCEUUS_RESURRECTION_COOLDOWN) {
            return;
        }

        int cooldownTicks = event.getValue();
        setCooldownActive(cooldownTicks > 0);

        if (cooldownTicks == 1) {
            startThrallTimer();
        }
    }

    @Override
    protected void sync() {
        int cooldownTicks = client.getVarbitValue(VarbitID.ARCEUUS_RESURRECTION_COOLDOWN);
        setCooldownActive(cooldownTicks > 0);

        updateActiveState(client.getVarbitValue(VarbitID.ARCEUUS_RESURRECTION_ACTIVE));
    }

    private void updateActiveState(int active) {
        if (active > 0 && !hasTrackedActiveEffect()) {
            markActiveWithoutKnownDuration();
        } else if (active == 0 && hasUnknownActiveDuration()) {
            clearActive();
        }
    }

    @Override
    public boolean isActive() {
        if (!hasTrackedActiveEffect()) {
            syncIfNeeded();
        }
        return super.isActive();
    }

    private void startThrallTimer() {
        int durationTicks = client.getBoostedSkillLevel(Skill.MAGIC);

        if (hasMasterCombatAchievements()) {
            durationTicks *= 2;
        }

        durationTicks += THRALL_SPAWN_DELAY_TICKS;

        markActive(TimeConstants.ticksToNanos(durationTicks));
    }

    private boolean hasMasterCombatAchievements() {
        return client.getVarbitValue(VarbitID.CA_TIER_STATUS_MASTER) == 2;
    }
}

package com.pvmhud.tracking;

import net.runelite.api.ChatMessageType;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

import javax.inject.Singleton;

@Singleton
public class MarkOfDarknessTracker extends BaseTimedSpellTracker {
    private static final String MARK_PLACED_MESSAGE =
            "you have placed a mark of darkness upon yourself.";
    private static final String MARK_FADED_MESSAGE =
            "your mark of darkness has faded away.";
    private static final String MARK_EXPIRING_MESSAGE =
            "your mark of darkness is about to run out.";

    @Subscribe
    public void onChatMessage(ChatMessage event) {
        if (event.getType() != ChatMessageType.GAMEMESSAGE) {
            return;
        }

        String message = Text.standardize(event.getMessage());

        if (message.endsWith(MARK_PLACED_MESSAGE)) {
            markActive(TimeConstants.ticksToNanos(getDurationTicks()));
        } else if (message.endsWith(MARK_EXPIRING_MESSAGE)) {
            setExpiringSoon(true);
        } else if (message.endsWith(MARK_FADED_MESSAGE)) {
            clearActive();
        }
    }

    @Override
    protected void sync() {
        setCooldownActive(false);
    }

    int getDurationTicks() {
        return estimateDurationTicks(client.getRealSkillLevel(Skill.MAGIC), isPurgingStaffEquipped());
    }

    static int estimateDurationTicks(int realMagicLevel, boolean purgingStaffEquipped) {
        int ticks = realMagicLevel * 3;

        if (purgingStaffEquipped) {
            ticks *= 5;
        }

        return ticks;
    }

    private boolean isPurgingStaffEquipped() {
        ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
        if (equipment == null) {
            return false;
        }

        Item weapon = equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
        return weapon != null && weapon.getId() == ItemID.PURGING_STAFF;
    }
}

package com.pvmhud.tracking;

public abstract class BaseTimedSpellTracker extends CachedVarbitTracker implements SpellStateTracker {
    private long activeStartedAtNanos;
    private long activeDurationNanos;
    private boolean activeWithoutKnownDuration;
    private boolean cooldownActive;
    private boolean expiringSoon;

    protected final void markActive(long durationNanos) {
        activeStartedAtNanos = System.nanoTime();
        activeDurationNanos = Math.max(0L, durationNanos);
        activeWithoutKnownDuration = false;
        expiringSoon = false;
    }

    protected final void markActiveWithoutKnownDuration() {
        activeStartedAtNanos = 0L;
        activeDurationNanos = 0L;
        activeWithoutKnownDuration = true;
        expiringSoon = false;
    }

    protected final void clearActive() {
        activeStartedAtNanos = 0L;
        activeDurationNanos = 0L;
        activeWithoutKnownDuration = false;
        expiringSoon = false;
    }

    protected final boolean hasUnknownActiveDuration() {
        return activeWithoutKnownDuration;
    }

    protected final boolean hasTrackedActiveEffect() {
        return activeWithoutKnownDuration || getRemainingNanos() > 0L;
    }

    protected final void setCooldownActive(boolean cooldownActive) {
        this.cooldownActive = cooldownActive;
    }

    protected final void setExpiringSoon(boolean expiringSoon) {
        this.expiringSoon = expiringSoon;
    }

    protected final long getRemainingNanos() {
        if (activeStartedAtNanos <= 0L || activeDurationNanos <= 0L) {
            return 0L;
        }

        return Math.max(0L, activeDurationNanos - (System.nanoTime() - activeStartedAtNanos));
    }

    @Override
    public String getDisplayText() {
        long remainingNanos = getRemainingNanos();
        if (remainingNanos <= 0L) {
            return "";
        }

        long seconds = (remainingNanos + TimeConstants.NS_PER_SECOND - 1L)
                / TimeConstants.NS_PER_SECOND;
        return Long.toString(seconds);
    }

    @Override
    public double getProgress() {
        if (activeWithoutKnownDuration || activeDurationNanos <= 0L) {
            return -1d;
        }

        return Math.min(1d, getRemainingNanos() / (double) activeDurationNanos);
    }

    @Override
    public boolean isActive() {
        return hasTrackedActiveEffect();
    }

    @Override
    public boolean hasActiveEffect() {
        return hasTrackedActiveEffect();
    }

    @Override
    public boolean isOnCooldown() {
        syncIfNeeded();
        return cooldownActive;
    }

    @Override
    public boolean isExpiringSoon(int soonWindowSeconds) {
        long remainingNanos = getRemainingNanos();
        if (remainingNanos <= 0L) {
            return false;
        }

        if (expiringSoon) {
            return true;
        }

        return remainingNanos <= TimeConstants.secondsToNanos(soonWindowSeconds);
    }

    @Override
    public void reset() {
        activeStartedAtNanos = 0L;
        activeDurationNanos = 0L;
        activeWithoutKnownDuration = false;
        cooldownActive = false;
        expiringSoon = false;
        invalidateCache();
    }
}

